-- crash-edit/pending-submission-count
-- How many submissions about a crash are still waiting for a decision. A crash with one cannot be published from the editor: the review queue decides it, with its two-reviewer rule (audit finding 4).
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--   $2 = "pending"
--
-- Generated by `pnpm db:queries` from lib/db/queries/crash-edit.ts. Do not edit by hand.

select count(*)
from "submissions"
where ("submissions"."target_id" = $1
  and "submissions"."status" = $2);
